(async function() {
  const accounts = [
    'huggingface', 'StabilityAI', 'midjourney', 'runwayml',
    'cloudbeds', 'Guesty', 'Hostfully', 'SiteMinder',
    'ElevenLabs', 'DeepgramAI', 'assemblyai',
    'hubspot', 'stripe', 'notionhq', 'figma', 'canva'
  ];

  const delay = ms => new Promise(r => setTimeout(r, ms));

  for (const acc of accounts) {
    // Navigate to follow page
    window.location.href = `https://x.com/intent/follow?screen_name=${acc}`;
    await delay(2000);

    // Click follow button
    const btn = document.querySelector('button[data-testid="confirmationSheetConfirm"]') || 
                Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Follow @'));
    if (btn) {
      btn.click();
      await delay(1000);
    }
  }

  return 'Batch complete';
})()

